Here's a complete, self-contained Snake game. I went with a warm paper-and-ink look instead of the usual neon-on-black, and the snake moves with sub-cell interpolation so it glides instead of jumping grid-square to grid-square — that's the detail that makes it feel good to play. The head has eyes that track the direction of travel, and the body is drawn as one continuous rounded stroke rather than blocks.

```html
<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1">
<title>Snake.</title>
<style>
  :root{
    --paper:#F4EFE3; --ink:#211C15; --accent:#D9482B; --muted:#8A8272;
  }
  *{box-sizing:border-box;margin:0;padding:0}
  html,body{height:100%}
  body{
    background:var(--paper); color:var(--ink);
    font-family:ui-monospace,"Cascadia Mono","SF Mono",Menlo,Consolas,monospace;
    display:flex; flex-direction:column; align-items:center; justify-content:center;
    min-height:100vh; padding:24px; gap:18px;
  }
  header{width:532px; display:flex; align-items:baseline; justify-content:space-between; border-bottom:2px solid var(--ink); padding-bottom:10px}
  h1{font-size:20px; font-weight:700; letter-spacing:.45em}
  h1 em{font-style:normal; color:var(--accent)}
  .sub{font-size:10px; letter-spacing:.18em; text-transform:uppercase; color:var(--muted)}
  .board{position:relative; width:532px}
  .board.shake{animation:shake .3s linear}
  @keyframes shake{
    0%,100%{transform:translate(0,0)} 20%{transform:translate(-4px,2px)}
    40%{transform:translate(4px,-2px)} 60%{transform:translate(-3px,-2px)} 80%{transform:translate(3px,2px)}
  }
  canvas{display:block; background:#FBF7EC; border:2px solid var(--ink)}
  .scorebar{width:532px; display:flex; justify-content:space-between; align-items:flex-end}
    .stat{text-align:left} .stat:last-child{text-align:right}
    .stat .label{font-size:10px; letter-spacing:.25em; text-transform:uppercase; color:var(--muted)}
    .stat .value{font-size:30px; font-weight:700; font-variant-numeric:tabular-nums; line-height:1.1; transition:transform .12s}
    .stat .value.pop{transform:scale(1.25)}
    .stat .value.accent{color:var(--accent)}
  .overlay{
    position:absolute; inset:2px; background:rgba(244,239,227,.88);
    display:flex; flex-direction:column; align-items:center; justify-content:center; gap:14px; text-align:center;
  }
  .overlay.hidden{display:none}
  .overlay h2{font-size:26px; letter-spacing:.3em; font-weight:700}
  .overlay p{font-size:12px; color:var(--muted); letter-spacing:.08em; max-width:340px; line-height:1.7}
  .overlay .final{font-size:44px; font-weight:700; font-variant-numeric:tabular-nums}
  .overlay .tag{font-size:10px; letter-spacing:.3em; color:var(--accent); text-transform:uppercase}
  button{
    font:inherit; font-size:12px; letter-spacing:.2em; text-transform:uppercase;
    background:var(--ink); color:var(--paper); border:none; padding:10px 26px; cursor:pointer;
  }
  button:hover{background:var(--accent)}
  .keys{display:flex; gap:18px; font-size:10px; letter-spacing:.12em; color:var(--muted); text-transform:uppercase; align-items:center}
  kbd{
    font:inherit; color:var(--ink); border:1px solid var(--ink); border-bottom-width:2px;
    border-radius:3px; padding:2px 6px; margin-right:4px; background:#FBF7EC;
  }
</style>
</head>
<body>

<header>
  <h1>SNAKE<em>.</em></h1>
  <div class="sub">paper edition</div>
</header>

<div class="scorebar">
  <div class="stat"><div class="label">Score</div><div class="value" id="score">0</div></div>
  <div class="stat"><div class="label">Best</div><div class="value accent" id="best">0</div></div>
</div>

<div class="board" id="board">
  <canvas id="cv"></canvas>
  <div class="overlay" id="overlay"></div>
</div>

<div class="keys">
  <span><kbd>&larr;&uarr;&darr;&rarr;</kbd>/<kbd>WASD</kbd> move</span>
  <span><kbd>Space</kbd> pause</span>
  <span><kbd>M</kbd> sound <span id="snd">on</span></span>
</div>

<script>
(() => {
  const COLS = 24, ROWS = 24, CELL = 22;
  const cv = document.getElementById('cv'), ctx = cv.getContext('2d');
  const dpr = Math.min(window.devicePixelRatio || 1, 2);
  cv.width = COLS*CELL*dpr; cv.height = ROWS*CELL*dpr;
  cv.style.width = COLS*CELL+'px'; cv.style.height = ROWS*CELL+'px';
  ctx.scale(dpr, dpr);

  const $score = document.getElementById('score'), $best = document.getElementById('best');
  const $overlay = document.getElementById('overlay'), $board = document.getElementById('board');
  const $snd = document.getElementById('snd');

  let snake, prev, dir, queue, food, score, interval, acc, phase, eatAt, lastTs;
  let best = +(localStorage.getItem('snake.best') || 0);
  $best.textContent = best;

  let soundOn = true, actx = null;
  function beep(f1, f2, dur, type, vol){
    if (!soundOn) return;
    try {
      actx = actx || new (window.AudioContext || window.webkitAudioContext)();
      const o = actx.createOscillator(), g = actx.createGain(), t = actx.currentTime;
      o.type = type; o.frequency.setValueAtTime(f1, t);
      o.frequency.exponentialRampToValueAtTime(f2, t + dur);
      g.gain.setValueAtTime(vol, t); g.gain.exponentialRampToValueAtTime(.0001, t + dur);
      o.connect(g).connect(actx.destination); o.start(t); o.stop(t + dur);
    } catch(e){}
  }

  function reset(){
    const cy = Math.floor(ROWS/2), cx = Math.floor(COLS/2) - 1;
    snake = [{x:cx, y:cy}, {x:cx-1, y:cy}, {x:cx-2, y:cy}];
    prev = snake.slice();
    dir = {x:1, y:0}; queue = [];
    score = 0; interval = 150; acc = 0; eatAt = -1e9;
    $score.textContent = 0;
    placeFood();
  }

  function onSnake(p){ return snake.some(s => s.x===p.x && s.y===p.y); }
  function placeFood(){
    do { food = {x:(Math.random()*COLS)|0, y:(Math.random()*ROWS)|0}; } while (onSnake(food));
  }

  function step(){
    if (queue.length){
      const d = queue.shift();
      if (!(d.x===-dir.x && d.y===-dir.y)) dir = d;
    }
    const head = {x:snake[0].x+dir.x, y:snake[0].y+dir.y};
    if (head.x<0 || head.x>=COLS || head.y<0 || head.y>=ROWS) return die();
    const grow = head.x===food.x && head.y===food.y;
    const lim = snake.length - (grow ? 0 : 1);
    for (let i=0;i<lim;i++) if (snake[i].x===head.x && snake[i].y===head.y) return die();
    prev = snake.slice();
    snake.unshift(head);
    if (grow){
      score += 10;
      interval = Math.max(70, 150 - (snake.length-3)*2.5);
      eatAt = performance.now();
      $score.textContent = score;
      $score.classList.remove('pop'); void $score.offsetWidth; $score.classList.add('pop');
      beep(520, 880, .09, 'square', .05);
      placeFood();
    } else snake.pop();
  }

  function die(){
    phase = 'over';
    const isBest = score > best;
    if (isBest){ best = score; localStorage.setItem('snake.best', best); $best.textContent = best; }
    beep(300, 90, .3, 'sawtooth', .07);
    $board.classList.remove('shake'); void $board.offsetWidth; $board.classList.add('shake');
    showOver(isBest);
  }

  /* ---- overlays ---- */
  function show(html){ $overlay.innerHTML = html; $overlay.classList.remove('hidden'); }
  function hide(){ $overlay.classList.add('hidden'); }
  function showReady(){
    show(`<h2>READY</h2><p>Press an arrow key or WASD to start.<br>Eat the red marks. Don't bite yourself.</p>`);
  }
  function showPaused(){
    show(`<h2>PAUSED</h2><p>Press space to resume.</p>`);
  }
  function showOver(isBest){
    show(`
      <div class="tag">${isBest && score>0 ? 'New best' : 'Game over'}</div>
      <div class="final">${score}</div>
      <p>Best ${best}</p>
      <button id="again">Play again</button>
      <p style="font-size:10px">or press Enter</p>`);
    document.getElementById('again').addEventListener('click', restart);
  }
  function restart(){ reset(); phase = 'running'; hide(); }

  /* ---- input ---- */
  const DIRS = {
    ArrowUp:{x:0,y:-1}, ArrowDown:{x:0,y:1}, ArrowLeft:{x:-1,y:0}, ArrowRight:{x:1,y:0},
    w:{x:0,y:-1}, s:{x:0,y:1}, a:{x:-1,y:0}, d:{x:1,y:0}
  };
  addEventListener('keydown', e => {
    const k = e.key.length===1 ? e.key.toLowerCase() : e.key;
    if (DIRS[k]){
      e.preventDefault();
      if (phase==='ready'){ phase='running'; hide(); }
      if (phase==='running'){
        const last = queue.length ? queue[queue.length-1] : dir;
        const d = DIRS[k];
        if (!(d.x===last.x && d.y===last.y) && queue.length<3) queue.push(d);
      }
    } else if (k===' '){
      e.preventDefault();
      if (phase==='running'){ phase='paused'; showPaused(); }
      else if (phase==='paused'){ phase='running'; hide(); }
      else if (phase==='over') restart();
    } else if (k==='Enter' && phase==='over'){ restart(); }
    else if (k==='m'){ soundOn=!soundOn; $snd.textContent = soundOn?'on':'off'; }
  });

  /* ---- render ---- */
  function render(t, now){
    ctx.clearRect(0,0,COLS*CELL,ROWS*CELL);

    // grid dots at intersections
    ctx.fillStyle = 'rgba(33,28,21,.10)';
    for (let x=1;x<COLS;x++) for (let y=1;y<ROWS;y++)
      ctx.fillRect(x*CELL-.5, y*CELL-.5, 1, 1);

    // food: pulsing dot + thin ring, like a target mark
    const fx = food.x*CELL+CELL/2, fy = food.y*CELL+CELL/2;
    const pr = CELL*.26*(1+.12*Math.sin(now/280));
    ctx.fillStyle = '#D9482B';
    ctx.beginPath(); ctx.arc(fx,fy,pr,0,7); ctx.fill();
    ctx.strokeStyle = 'rgba(217,72,43,.45)'; ctx.lineWidth = 1.5;
    ctx.beginPath(); ctx.arc(fx,fy,pr+4.5,0,7); ctx.stroke();

    // snake: interpolated continuous stroke
    const pts = snake.map((p,i) => {
      const q = prev[Math.min(i, prev.length-1)];
      return {
        x:(q.x+(p.x-q.x)*t)*CELL+CELL/2,
        y:(q.y+(p.y-q.y)*t)*CELL+CELL/2
      };
    });
    ctx.strokeStyle = '#211C15';
    ctx.lineWidth = CELL*.62; ctx.lineCap = 'round'; ctx.lineJoin = 'round';
    ctx.beginPath(); ctx.moveTo(pts[0].x, pts[0].y);
    for (let i=1;i<pts.length;i++) ctx.lineTo(pts[i].x, pts[i].y);
    ctx.stroke();

    // head + eyes looking where we're going
    const bump = Math.max(0, 1-(now-eatAt)/180)*.16;
    const hr = CELL*.44*(1+bump);
    ctx.fillStyle = '#211C15';
    ctx.beginPath(); ctx.arc(pts[0].x, pts[0].y, hr, 0, 7); ctx.fill();
    const px = -dir.y, py = dir.x; // perpendicular
    for (const s of [-1,1]){
      const ex = pts[0].x + dir.x*CELL*.10 + px*s*CELL*.15;
      const ey = pts[0].y + dir.y*CELL*.10 + py*s*CELL*.15;
      ctx.fillStyle = '#FBF7EC';
      ctx.beginPath(); ctx.arc(ex,ey,2.6,0,7); ctx.fill();
      ctx.fillStyle = '#211C15';
      ctx.beginPath(); ctx.arc(ex+dir.x*1.1, ey+dir.y*1.1, 1.2, 0, 7); ctx.fill();
    }
  }

  /* ---- loop ---- */
  function loop(ts){
    const dt = Math.min(ts-(lastTs??ts), 100); lastTs = ts;
    if (phase==='running'){
      acc += dt;
      while (acc >= interval && phase==='running'){ acc -= interval; step(); }
    }
    const t = phase==='running' ? Math.min(acc/interval, 1) : 1;
    if (phase!=='over') render(t, ts);
    requestAnimationFrame(loop);
  }

  reset(); phase = 'ready'; showReady();
  requestAnimationFrame(loop);
})();
</script>
</body>
</html>
```

A few implementation notes:

- **Smooth motion** — the game logic ticks on a timer, but rendering interpolates every segment between its previous and current grid position (`t = acc/interval`), so movement is fluid at any speed. The body is a single polyline stroke with round joins, not blocks.
- **Input** — arrows and WASD both work; turns are queued (up to 3) so quick double-turns register correctly, with reversal guards. Space pauses/resumes, Enter or the button restarts from the game-over screen.
- **Progression** — each food is +10 points and shaves ~2.5 ms off the tick interval, bottoming out at 70 ms. Best score persists in `localStorage`.
- **Details** — the head's eyes track the direction of travel and the head gives a little scale-pop on eating; the score numeral pops in sync; death gets a brief board shake; the food pulses like a target mark. There's also a tiny WebAudio blip on eat/death (no audio files), toggle with `M`.
- **Crisp rendering** — the canvas is scaled by `devicePixelRatio` so lines stay sharp on retina screens.

Here's my take on the Halcyon VX-9 — I went for a warm amber-on-charcoal "vintage panel" aesthetic with a fully CSS-drawn synth whose keys and demo arp actually make sound via WebAudio (no assets needed):

```html
<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0>
<title>Halcyon VX-9 — Analogue Synthesizer</title>
<style>
  :root{
    --bg:#0f0d0a; --panel:#16130f; --panel2:#1b1712; --ink:#ece3d0; --mut:#9b8f7a;
    --line:#2b251c; --amber:#e5a13d; --amber-dim:#8a6224; --green:#8fd98a; --red:#e0653f;
    --mono:ui-monospace,"SF Mono",Menlo,Consolas,monospace;
    --disp:"Futura","Futura PT","Century Gothic","Avenir Next","Helvetica Neue",sans-serif;
  }
  *{margin:0;padding:0;box-sizing:border-box}
  html{scroll-behavior:smooth}
  body{background:var(--bg);color:var(--ink);font-family:var(--disp);line-height:1.55;-webkit-font-smoothing:antialiased}
  ::selection{background:var(--amber);color:#141005}
  a{color:inherit;text-decoration:none}
  section{scroll-margin-top:80px}
  .wrap{max-width:1180px;margin:0 auto;padding:0 24px}
  .mono{font-family:var(--mono)}
  .eyebrow{font-family:var(--mono);font-size:11px;letter-spacing:.22em;color:var(--amber);text-transform:uppercase}
  h2{font-size:clamp(28px,4vw,44px);letter-spacing:-.02em;font-weight:600;line-height:1.1}
  .sub{color:var(--mut);max-width:52ch}
  .btn{display:inline-block;font-family:var(--mono);font-size:12px;letter-spacing:.12em;text-transform:uppercase;
    padding:14px 26px;background:var(--amber);color:#181104;border:1px solid var(--amber);cursor:pointer;
    transition:transform .15s,background .15s,color .15s}
  .btn:hover{transform:translateY(-2px);background:#f2b355}
  .btn.ghost{background:transparent;color:var(--ink);border-color:#4a4232}
  .btn.ghost:hover{border-color:var(--amber);color:var(--amber)}
  :focus-visible{outline:2px solid var(--amber);outline-offset:3px}

  /* ---------- nav ---------- */
  nav{position:fixed;inset:0 0 auto;z-index:50;background:rgba(15,13,10,.82);backdrop-filter:blur(10px);border-bottom:1px solid var(--line)}
  .navin{display:flex;align-items:center;justify-content:space-between;height:64px}
  .logo{font-family:var(--mono);letter-spacing:.3em;font-size:13px}
  .logo b{color:var(--amber);font-weight:400}
  .navlinks{display:flex;gap:32px;font-family:var(--mono);font-size:11px;letter-spacing:.14em;text-transform:uppercase;color:var(--mut)}
  .navlinks a:hover{color:var(--amber)}
  .nav .btn{padding:9px 18px}
  @media(max-width:720px){.navlinks{display:none}}

  /* ---------- hero ---------- */
  .hero{padding:150px 0 70px;display:grid;grid-template-columns:1.02fr .98fr;gap:56px;align-items:center;position:relative}
  .hero::before{content:"";position:absolute;right:-10%;top:10%;width:640px;height:640px;border-radius:50%;
    background:radial-gradient(circle,rgba(229,161,61,.07),transparent 65%);pointer-events:none}
  h1{font-size:clamp(72px,9vw,132px);letter-spacing:-.035em;line-height:.95;font-weight:600;margin:18px 0 20px}
  h1 em{font-style:normal;color:var(--amber)}
  .hero p.lede{color:var(--mut);font-size:17px;max-width:44ch;margin-bottom:32px}
  .cta{display:flex;gap:14px;flex-wrap:wrap}
  .herostats{display:flex;gap:36px;margin-top:44px;border-top:1px solid var(--line);padding-top:20px}
  .herostats div strong{display:block;font-size:22px;letter-spacing:-.02em}
  .herostats div span{font-family:var(--mono);font-size:10px;letter-spacing:.16em;color:var(--mut);text-transform:uppercase}

  /* ---------- the synth (pure CSS) ---------- */
  .synthstage{position:relative;width:100%;max-width:660px}
  .synth{width:660px;transform-origin:top left;background:linear-gradient(#221d16,#191510);
    border:1px solid #060504;border-radius:10px;position:relative;
    box-shadow:0 30px 60px rgba(0,0,0,.55),inset 0 1px 0 rgba(255,255,255,.07);
    padding:16px 30px 18px 40px}
  .synth::before,.synth::after{content:"";position:absolute;top:0;bottom:0;width:16px;border-radius:10px 0 0 10px;
    background:repeating-linear-gradient(90deg,#5a3f24 0 2px,#6b4b2c 2px 5px,#4e361f 5px 8px);left:0;box-shadow:inset -2px 0 4px rgba(0,0,0,.4)}
  .synth::after{left:auto;right:0;border-radius:0 10px 10px 0;box-shadow:inset 2px 0 4px rgba(0,0,0,.4)}
  .rowA{display:flex;justify-content:space-between;align-items:flex-start;margin-bottom:12px}
  .plate{font-family:var(--mono);font-size:10px;letter-spacing:.34em;color:var(--mut)}
  .plate b{display:block;color:var(--ink);font-size:13px;letter-spacing:.3em;font-weight:400}
  .plate b i{font-style:normal;color:var(--amber)}
  .screenwrap{display:flex;flex-direction:column;align-items:flex-end;gap:7px}
  .screen{width:172px;background:#0b0906;border:1px solid #000;border-radius:3px;padding:7px 10px;
    font-family:var(--mono);font-size:9px;line-height:1.5;color:var(--amber);letter-spacing:.08em;
    box-shadow:inset 0 0 12px rgba(229,161,61,.12)}
  .screen .cur{animation:blink 1.1s steps(1) infinite}
  @keyframes blink{50%{opacity:0}}
  .leds{display:flex;gap:7px}
  .led{width:6px;height:6px;border-radius:50%;background:#3a3121;transition:.3s}
  .led.g{background:#26402a}.led.r{background:#4b2417}
  .synth:not(.off) .led{background:var(--green);box-shadow:0 0 6px rgba(143,217,138,.7);animation:pulse 1.6s infinite}
  .synth:not(.off) .led.a{background:var(--amber);box-shadow:0 0 6px rgba(229,161,61,.7)}
  .synth:not(.off) .led.r{background:var(--red);box-shadow:0 0 6px rgba(224,101,63,.7)}
  .led:nth-child(2){animation-delay:.2s!important}.led:nth-child(3){animation-delay:.4s!important}
  .led:nth-child(4){animation-delay:.6s!important}.led:nth-child(5){animation-delay:.8s!important}
  @keyframes pulse{50%{opacity:.45}}
  .rowB{display:flex;gap:22px;align-items:flex-start;padding:10px 0 14px;border-top:1px solid #2c261d;border-bottom:1px solid #2c261d}
  .kgroup{display:flex;flex-direction:column;gap:6px}
  .krow{display:flex;gap:9px}
 .klabel,.flabel{font-family:var(--mono);font-size:8px;letter-spacing:.2em;color:var(--mut);text-transform:uppercase;text-align:center}
  .knobcol{display:flex;flex-direction:column;align-items:center;gap:4px}
  .knob{width:38px;height:38px;border-radius:50%;cursor:pointer;position:relative;transform:rotate(var(--r,0deg));
    background:radial-gradient(circle at 34% 28%,#4a4335,#221d14 68%,#171310);
    border:1px solid #0a0805;box-shadow:0 3px 6px rgba(0,0,0,.5),inset 0 1px 0 rgba(255,255,255,.1);
    transition:transform .18s}
  .knob::before{content:"";position:absolute;top:3px;left:calc(50% - 1px);width:2px;height:11px;background:var(--amber)}
  .knob:hover{box-shadow:0 3px 6px rgba(0,0,0,.5),inset 0 1px 0 rgba(255,255,255,.1),0 0 0 2px rgba(229,161,61,.25)}
  .rowC{display:flex;align-items:flex-end;gap:26px;padding:14px 0 12px}
  .faders{display:flex;gap:14px}
  .fcol{display:flex;flex-direction:column;align-items:center;gap:5px}
  .fader{width:22px;height:86px;position:relative;cursor:pointer}
  .fader::before{content:"";position:absolute;left:50%;top:2px;bottom:2px;width:2px;background:#0a0805;box-shadow:1px 0 0 rgba(255,255,255,.06)}
  .fader i{position:absolute;left:0;right:0;height:12px;background:linear-gradient(#3d362a,#241f16);
    border:1px solid #0a0805;border-radius:2px;box-shadow:0 2px 4px rgba(0,0,0,.5),inset 0 1px 0 rgba(255,255,255,.12)}
  .fader i::after{content:"";position:absolute;left:3px;right:3px;top:5px;height:1px;background:var(--amber)}
  .vdiv{width:1px;align-self:stretch;background:#2c261d}
  .swcol{display:flex;flex-direction:column;gap:9px}
  .sw{width:34px;height:14px;border:1px solid #0a0805;border-radius:2px;background:#14100b;position:relative;cursor:pointer;box-shadow:inset 0 1px 3px rgba(0,0,0,.6)}
  .sw::after{content:"";position:absolute;top:1px;bottom:1px;left:1px;width:15px;background:linear-gradient(#4a4335,#2a241a);border-radius:1px;transition:.15s}
  .sw.on::after{left:16px;background:linear-gradient(#6b5a33,var(--amber-dim))}
  .patches{display:grid;grid-template-columns:1fr 1fr;gap:6px}
  .pbtn{width:30px;height:22px;background:#14100b;border:1px solid #0a0805;border-radius:2px;color:var(--mut);
    font-family:var(--mono);font-size:9px;cursor:pointer;box-shadow:inset 0 1px 0 rgba(255,255,255,.06)}
  .pbtn.act{color:var(--amber);border-color:var(--amber-dim);box-shadow:inset 0 0 6px rgba(229,161,61,.2)}
  .rowD{display:flex;gap:14px;align-items:stretch}
  .wheels{display:flex;gap:6px;align-items:center;padding-bottom:6px}
  .wheel{width:34px;height:74px;border-radius:0 0 40px 40px/0 0 34px 34px? }
  .wheel{width:32px;height:72px;border:1px solid #0a0805;border-top:none;
    background:radial-gradient(120% 120% at 50% 0,#3a3327,#1c1811 70%);border-radius:0 0 16px 16px;
    box-shadow:inset 0 3px 6px rgba(0,0,0,.5);position:relative}
  .wheel::after{content:"";position:absolute;left:50%;top:8px;bottom:8px;width:1px;background:rgba(229,161,61,.5)}
  .keys{flex:1;height:104px;display:flex;position:relative;border-radius:0 0 4px 4px;overflow:hidden;box-shadow:0 4px 8px rgba(0,0,0,.4)}
  .wk{flex:1;background:linear-gradient(#f2ecdc,#cfc7b2);border-right:1px solid #8f887a;cursor:pointer;position:relative;transition:background .1s}
  .wk:last-child{border-right:none}
  .wk.press,.wk.lit{background:linear-gradient(#ffe9bd,#e5c98a)}
  .bk{position:absolute;top:0;height:58%;width:5.2%;background:linear-gradient(#2c261d,#0f0c08);border:1px solid #000;border-top:none;border-radius:0 0 3px 3px;cursor:pointer;z-index:2;transition:background .1s}
  .bk.press,.bk.lit{background:linear-gradient(#5c4a22,#3a2f14)}
  .synth.off .screen{color:#5c4d2e}
  .synth.off .led{box-shadow:none}
  .synth.off .knob::before,.synth.off .fader i::after{background:#6b6250}

  /* ---------- ticker ---------- */
  .ticker{border-top:1px solid var(--line);border-bottom:1px solid var(--line);overflow:hidden;padding:13px 0;margin:30px 0 0}
  .tk{display:flex;gap:48px;width:max-content;animation:tick 26s linear infinite;font-family:var(--mono);font-size:11px;letter-spacing:.22em;color:var(--mut);text-transform:uppercase;white-space:nowrap}
  .tk b{color:var(--amber);font-weight:400}
  @keyframes tick{to{transform:translateX(-50%)}}

  /* ---------- sections ---------- */
  .sect{padding:96px 0}
  .shead{display:flex;justify-content:space-between;align-items:flex-end;gap:24px;margin-bottom:44px;flex-wrap:wrap}
  .shead .num{font-family:var(--mono);color:var(--amber-dim);font-size:12px;letter-spacing:.2em}

  /* features: precise 12-col grid, hairline dividers */
  .features{display:grid;grid-template-columns:repeat(12,1fr);gap:1px;background:var(--line);border:1px solid var(--line)}
